{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C59"],
      "claim": "Probenecid, which shares the sulfonamide and carboxylic acid motif with the query, has ~100% oral bioavailability in humans, directly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Sodium salicylate, a small carboxylic acid/phenol, showed complete absolute bioavailability after oral administration in humans, supporting high F for the acid-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Ketoprofen, a carboxylic acid drug, had 84.5% absolute oral bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Encainide, a basic-amine analogue with relatively lower bioavailability, still showed 32±7% F in normal subjects, above the 20% threshold, so it supports high classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Solifenacin, a basic amine with aromatic groups, had 88% absolute bioavailability in healthy volunteers, showing that basic amine/phenol-ether features do not preclude high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query's carboxylic acid/sulfonamide core is directly mirrored by probenecid (100% F) and salicylate (complete F); other carboxylic acid and basic-amine analogues are all above the 20% threshold. High oral bioavailability at F≥20% is therefore best supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the query molecule.",
    "The single unquantified 'poor' pethidine record is a one-patient outlier and not threshold-specific.",
    "Potential first-pass metabolism or transporter effects of the pyrrolidine and phenoxy ether are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

